2. Limited to Certain Types: Switch statements are mainly designed for int, char, or string values depending on the language.
            C++

    #include <iostream>
using namespace std;

int main()
{
    char grade = 'B';

    switch (grade)
    {
    case 'A':
        cout << "Excellent!" << endl;
        break;
    case 'B':
        cout << "Good!" << endl;
        break;
    default:
        cout << "Not specified." << endl;
    }

    return 0;
}


